package com.bank.offheap;

import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Simulates an OFF-HEAP leak: direct buffers kept alive → native RSS grows,
// but the Java HEAP stays tiny (only small wrapper objects live on it).
class DirectLeakService {
    private static final Logger log = Logger.getLogger(DirectLeakService.class.getName());
    // holding the wrappers prevents their cleaner from freeing native memory
    private final List<ByteBuffer> retained = new ArrayList<>();

    void streamStatementPdf(String accountId, int sizeMb) {
        // real code would use this buffer to stream a PDF, then let it be freed;
        // the BUG is retaining it, so native memory is never returned.
        ByteBuffer buf = ByteBuffer.allocateDirect(sizeMb * 1024 * 1024);
        retained.add(buf);
        log.fine(() -> "Allocated " + sizeMb + "MB direct buffer for " + accountId);
    }

    int retainedCount() { return retained.size(); }

    // FIX: do NOT retain; let the buffer go out of scope so its cleaner frees native mem,
    // or for Netty ByteBuf call release(); clear here so the demo JVM survives.
    void releaseForDemo() { retained.clear(); }
}
