package com.bank.offheap;

import java.lang.management.BufferPoolMXBean;
import java.lang.management.ManagementFactory;
import java.util.List;
import java.util.logging.Logger;

// Reads the "direct" BufferPool MBean — shows native direct memory a heap dump misses.
class NativeMemoryProbe {
    private static final Logger log = Logger.getLogger(NativeMemoryProbe.class.getName());

    static void report(String phase) {
        List<BufferPoolMXBean> pools =
            ManagementFactory.getPlatformMXBeans(BufferPoolMXBean.class);
        Runtime rt = Runtime.getRuntime();
        long heapUsedMb = (rt.totalMemory() - rt.freeMemory()) / (1024 * 1024);
        for (BufferPoolMXBean pool : pools) {
            if ("direct".equals(pool.getName())) {
                long directMb = pool.getMemoryUsed() / (1024 * 1024);
                log.info(phase + " → heap used=" + heapUsedMb + "MB (clean), "
                    + "DIRECT off-heap=" + directMb + "MB (this is where RSS grows)");
            }
        }
    }
}
