package com.bank.offheap;

import java.util.logging.Logger;

public class OffHeapLeakDemo {
    private static final Logger log = Logger.getLogger(OffHeapLeakDemo.class.getName());

    public static void main(String[] args) {
        log.info("RSS will grow but the HEAP stays clean → off-heap direct-buffer leak");
        DirectLeakService service = new DirectLeakService();

        NativeMemoryProbe.report("before");
        for (int i = 0; i < 20; i++) {
            service.streamStatementPdf("SAV2001", 8);   // 8MB direct each, retained
        }
        NativeMemoryProbe.report("after 20 x 8MB");
        log.severe("Retained " + service.retainedCount() + " direct buffers (~"
            + (service.retainedCount() * 8) + "MB off-heap). A heap dump shows NONE of this."
            + " Use: jcmd <pid> VM.native_memory summary ; pmap -x <pid> ; async-profiler -e malloc");

        service.releaseForDemo();   // let cleaners free native memory
    }
}
